def render_plugins_configuration(self, user_params_json):
    user_params = load_user_params_from_json(user_params_json)

    # Use a different plugin configuration based on user_params
    if user_params.build_type.value == 'flatpak':
        return FlatpakPluginsConfiguration(user_params).render()
    elif user_params.build_type.value == 'scratch':
        return ScratchPluginsConfiguration(user_params).render()
    else:
        return DefaultPluginsConfiguration(user_params).render()
